import sys
cost={};deps={}
for l in sys.stdin.read().split('\n'):
    w=l.split()
    if not w: continue
    if w[0]=='task': cost[w[1]]=int(w[2]); deps.setdefault(w[1],set())
    else: deps.setdefault(w[1],set()).update(w[2:])
W=int(sys.argv[1])
pr={}
def P(u):
    if u in pr: return pr[u]
    pr[u]=cost[u]+max([P(v) for v in deps if u in deps[v]],default=0); return pr[u]
fin={};free=[0]*W;runs=[[] for _ in range(W)];t=0
while len(fin)<len(cost):
    while True:
        fw=[i for i in range(W) if free[i]<=t]
        rd=sorted([u for u in cost if u not in fin and all(d in fin and fin[d]<=t for d in deps[u])],key=lambda u:(-P(u),u))
        if not fw or not rd: break
        u=rd[0];i=fw[0];fin[u]=t+cost[u];free[i]=fin[u];runs[i].append(f"{u}@{t}-{fin[u]}")
    if len(fin)==len(cost): break
    t=min(f for f in free if f>t)
for i in range(W): print(f"worker {i}:"+"".join(" "+r for r in runs[i]))
print("makespan",max(fin.values(),default=0))
