/** Parses an address into {col,row,key,name}, or null when it is outside the addressable range. */
export function parseAddress(text) {
  const m = ADDR.exec(text)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row, key: col * 1000 + row, name: letters + row }
}

export function colName(col) {
  return col <= 26
    ? String.fromCharCode(64 + col)
    : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  for (let i = 0; i < lines.length; i++) {
    const rest = lines[i].replace(/^[ \t]+/, '')
    if (rest === '' || rest[0] === '#') continue
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(rest)
    const token = m[1]
    const addr = parseAddress(token)
    if (!addr) return { error: `error: line ${i + 1}: invalid cell address ${token}` }
    if (seen.has(addr.key)) return { error: `error: line ${i + 1}: cell ${addr.name} is declared twice` }
    seen.add(addr.key)
    cells.push({ ...addr, content: m[2] })
  }
  cells.sort((a, b) => a.col - b.col || a.row - b.row)
  return { cells }
}
