const FAIL = Symbol('fail')

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

/** Returns an AST, or null when the grammar rejects the body. A misplaced range yields {type:'bad', deps}. */
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let pos = 0
  let misplaced = false
  const isOp = (v) => pos < toks.length && toks[pos].t === 'op' && toks[pos].v === v
  const fail = () => { throw FAIL }

  function cmp() {
    let l = add()
    while (pos < toks.length && toks[pos].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[pos].v)) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l: noRange(l), r: noRange(add()) }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l: noRange(l), r: noRange(mul()) }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l: noRange(l), r: noRange(pow()) }
    }
    return l
  }
  function pow() {
    const base = signed()
    if (isOp('^')) {
      pos++
      return { type: 'bin', op: '^', l: noRange(base), r: noRange(pow()) }
    }
    return base
  }
  function signed() {
    if (isOp('-') || isOp('+')) {
      const op = toks[pos++].v
      return { type: 'un', op, e: noRange(signed()) }
    }
    return atom()
  }
  function noRange(n) {
    if (n.type === 'range') misplaced = true
    return n
  }
  function atom() {
    if (pos >= toks.length) fail()
    const tk = toks[pos]
    if (tk.t === 'num') { pos++; return { type: 'num', v: tk.v } }
    if (tk.t === 'op' && tk.v === '(') {
      pos++
      const e = noRange(cmp())
      if (!isOp(')')) fail()
      pos++
      return e
    }
    if (tk.t === 'word') {
      pos++
      if (isOp('(')) {
        pos++
        const args = []
        if (!isOp(')')) {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { pos++; continue }
            break
          }
        }
        if (!isOp(')')) fail()
        pos++
        return { type: 'call', name: tk.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        pos++
        if (pos >= toks.length || toks[pos].t !== 'word') fail()
        const b = toks[pos++].v
        return { type: 'range', a: parseAddress(tk.v), b: parseAddress(b) }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', a: parseAddress(tk.v) }
    }
    fail()
  }

