    const ast = cmp()
    if (pos !== toks.length) return null
    if (ast.type === 'range') misplaced = true
    return misplaced ? { type: 'bad', inner: ast } : ast
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
