  return out
}

/** Sorted distinct addresses (names) the AST names. */
export function collectDeps(ast) {
  const keys = new Set()
  const walk = (n) => {
    switch (n.type) {
      case 'bad': walk(n.inner); break
      case 'ref': if (n.a) keys.add(n.a.key); break
      case 'range': for (const k of rangeCells(n)) keys.add(k); break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  return [...keys].sort((a, b) => a - b).map((k) => {
    const col = Math.floor(k / 1000), row = k % 1000
    const letters = col <= 26
      ? String.fromCharCode(64 + col)
      : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
    return letters + row
  })
}
