class Err {
  constructor(token) { this.token = token }
}
const E = {
  div: new Err('#DIV/0!'), ref: new Err('#REF!'), value: new Err('#VALUE!'),
  cycle: new Err('#CYCLE!'), name: new Err('#NAME?'), err: new Err('#ERR!'),
}
const TOKENS = new Map(Object.values(E).map((e) => [e.token, e]))

export function formatValue(v) {
  if (v instanceof Err) return v.token
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

const isErr = (v) => v instanceof Err
const num = (x) => (Number.isFinite(x) ? x : E.div)
function toNum(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E.value
}
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)
function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (ra === 1) {
    const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
    for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
    return x.length - y.length
  }
  return Number(a) - Number(b)
}

export function evaluateAll(cells) {
  const decl = new Map(cells.map((c) => [c.key, c]))
  const memo = new Map()
  const busy = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const c = decl.get(key)
    if (!c) return 0
    if (busy.has(key)) return E.cycle
    busy.add(key)
    const v = literalOrFormula(c.content)
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function literalOrFormula(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast || ast.type === 'bad') return E.err
      return ev(ast)
    }
    if (content === '') return 0
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return Number(content)
    if (TOKENS.has(content)) return TOKENS.get(content)
    return content
  }

  function ev(n) {
    switch (n.type) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'ref': return n.a ? cellValue(n.a.key) : E.ref
      case 'un': {
        const v = ev(n.e)
        if (isErr(v)) return v
        const x = toNum(v)
        if (isErr(x)) return x
        return n.op === '-' ? -x : x
      }
      case 'bin': {
        const l = ev(n.l), r = ev(n.r)
        if (isErr(l)) return l
        if (isErr(r)) return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          switch (n.op) {
            case '=': return c === 0
            case '<>': return c !== 0
            case '<': return c < 0
            case '<=': return c <= 0
            case '>': return c > 0
            default: return c >= 0
          }
        }
        const a = toNum(l)
        if (isErr(a)) return a
        const b = toNum(r)
        if (isErr(b)) return b
        switch (n.op) {
          case '+': return num(a + b)
          case '-': return num(a - b)
          case '*': return num(a * b)
          case '/': return b === 0 ? E.div : num(a / b)
          default: return num(a ** b)
        }
      }
      case 'call': return call(n)
    }
    return E.err
  }

  function flatten(args) {
    const vals = []
    for (const a of args) {
      if (a.type === 'range') {
        if (!a.a || !a.b) vals.push(E.ref)
        else for (const k of rangeCells(a)) vals.push(cellValue(k))
      } else vals.push(ev(a))
    }
    return vals
  }

  function call(n) {
    const { name, args } = n
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return E.name
    if (name === 'IF' ? args.length !== 3 : name === 'ABS' ? args.length !== 1 : args.length < 1) return E.err
    if (name === 'IF' || name === 'ABS') {
      if (args.some((a) => a.type === 'range')) return E.err
    }
    if (name === 'IF') {
      const c = ev(args[0])
      if (isErr(c)) return c
      let t
      if (typeof c === 'boolean') t = c
      else if (typeof c === 'number') t = c !== 0
      else return E.value
      return ev(t ? args[1] : args[2])
    }
    const vals = flatten(args)
    for (const v of vals) if (isErr(v)) return v
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (isErr(x)) return x
      nums.push(x)
    }
    switch (name) {
      case 'ABS': return Math.abs(nums[0])
      case 'SUM': return num(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return Math.min(...nums)
      case 'MAX': return Math.max(...nums)
      default: return num(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  const out = new Map()
  for (const c of cells) out.set(c.key, cellValue(c.key))
  return out
}
"}

