/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula, collectDeps } from './formula.js'
import { evaluateAll, formatValue } from './eval.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const parsed = parseSheet(readFileSync(0, 'utf8'))
if (parsed.error) {
  process.stderr.write(parsed.error + '\n')
  process.exit(2)
}

const cells = parsed.cells
let out = ''
if (mode === 'values') {
  const values = evaluateAll(cells)
  for (const c of cells) out += `${c.name}=${formatValue(values.get(c.key))}\n`
} else {
  for (const c of cells) {
    let line = `${c.name}:`
    if (c.content.startsWith('=')) {
      const ast = parseFormula(c.content.slice(1))
      if (ast) for (const d of collectDeps(ast)) line += ' ' + d
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

