import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isAlpha = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdent = (c) => isAlpha(c) || isDigit(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isAlpha(c)) {
      let s = ''
      while (isIdent(cs[i])) s += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const run = (ok) => {
        let any = false
        for (;;) {
          if (ok(cs[i])) { s += adv(); any = true }
          else if (any && cs[i] === '_' && ok(cs[i + 1])) { s += adv() }
          else break
        }
        return any
      }
      const p = cs[i + 1]
      let ok = null
      if (c === '0' && (p === 'x' || p === 'X')) ok = isHex
      else if (c === '0' && (p === 'b' || p === 'B')) ok = (d) => d === '0' || d === '1'
      else if (c === '0' && (p === 'o' || p === 'O')) ok = (d) => d !== undefined && d >= '0' && d <= '7'
      if (ok) {
        s += adv(); s += adv()
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1], b = cs[i + 2]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(b))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            run(isDigit)
          }
        }
      }
      if (bad || isIdent(cs[i])) {
        while (isIdent(cs[i])) s += adv()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) v += simple[e]
        else if (e === 'x') {
          if (isHex(cs[i]) && isHex(cs[i + 1])) {
            v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16)); adv(); adv()
          } else throw new ScanError(bl, bc, 'invalid escape \\x')
        } else if (e === 'u') {
          let j = i
          let ok = cs[j] === '{'
          let h = ''
          if (ok) {
            j++
            while (isHex(cs[j])) h += cs[j++]
            ok = h.length > 0 && cs[j] === '}' && parseInt(h, 16) <= 0x10ffff
          }
          if (!ok) throw new ScanError(bl, bc, 'invalid escape \\u')
          v += String.fromCodePoint(parseInt(h, 16))
          while (i <= j) adv()
        } else throw new ScanError(bl, bc, `invalid escape \\${e}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT.includes(two)) { adv(); adv(); tokens.push({ line: sl, col: sc, kind: 'punct', body: two }); continue }
    if (PUNCT1.has(c)) { adv(); tokens.push({ line: sl, col: sc, kind: 'punct', body: c }); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  let out = ''
  if (mode === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
