const NAME = /^[A-Za-z0-9_-]+$/

function fail(msg) {
  const e = new Error(msg)
  e.election = true
  return e
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null || ballots.length > 0) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) throw fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) throw fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) throw fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) throw fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) throw fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      throw fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  }
  if (candidates === null) throw fail('error: no candidates')
  return { candidates, ballots }
}

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.prefs.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    const total = ballots.reduce((s, b) => s + b.count, 0n)
    for (const [c, v] of votes) history.get(c).push(v)
    const listing = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const round = { listing, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = listing.find(([, v]) => v * 2n > active)
    if (top) return { rounds, winner: top[0] }
    let min = listing[listing.length - 1][1]
    let tied = listing.filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; tied.length > 1 && r < rounds.length; r++) {
      const m = tied.reduce((a, c) => (history.get(c)[r] < a ? history.get(c)[r] : a), history.get(tied[0])[r])
      tied = tied.filter((c) => history.get(c)[r] === m)
    }
    const out = tied.reduce((a, c) => (c > a ? c : a))
    round.eliminated = out
    continuing.delete(out)
  }
}
