      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return changes
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [
    ...diff(base, mine).map(c => ({ ...c, side: 0 })),
    ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)

  const out = []
  let conflict = false
  const sides = [mine, theirs]
  let pos = 0, k = 0
  while (k < all.length) {
    if (all[k].bs > pos) {
      const n = all[k].bs - pos
      if (mode === 'regions') out.push(`stable ${n}`)
      else out.push(...base.slice(pos, all[k].bs))
    }
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    pos = re
    const baseLines = base.slice(rs, re)
    const rep = [0, 1].map(s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseLines
      const minB = Math.min(...cs.map(c => c.bs)), maxB = Math.max(...cs.map(c => c.be))
      const minS = Math.min(...cs.map(c => c.ss)), maxS = Math.max(...cs.map(c => c.se))
      return sides[s].slice(minS - (minB - rs), maxS + (re - maxB))
    })
    const [m, t] = rep
    let kind, res
    if (eq(m, t)) { kind = 'both'; res = m }
    else if (eq(m, baseLines)) { kind = 'theirs'; res = t }
    else if (eq(t, baseLines)) { kind = 'mine'; res = m }
    else kind = 'conflict'
    if (group.length === 1 && kind !== 'both') kind = group[0].side === 0 ? 'mine' : 'theirs'
    if (kind === 'conflict') {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseLines)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    } else if (mode === 'regions') out.push(`${kind} ${res.length}`)
    else out.push(...res)
  }
  if (pos < base.length) {
    if (mode === 'regions') out.push(`stable ${base.length - pos}`)
    else out.push(...base.slice(pos))
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
  process.exit(conflict ? 1 : 0)
}

main()
