  if (mode === 'pack') {
    const { lines, makespan } = pack(graph, workers)
    out = lines.join('\n') + '\nmakespan ' + makespan + '\n'
  } else if (mode === 'waves') {
    const waves = []
    for (const name of info.names) {
      const d = info.depth.get(name)
      ;(waves[d] ||= []).push(name)
    }
    waves.forEach((w, k) => { out += `wave ${k}: ${w.join(' ')}\n` })
    out += `total ${info.total}\n`
  } else {
    for (const n of info.names) {
      out += `${n} start=${info.start.get(n)} finish=${info.finish.get(n)} depth=${info.depth.get(n)}\n`
    }
    out += `total ${info.total}\n`
  }
