export class GraphError extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const NAME = /^[A-Za-z0-9_.-]+$/

export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const deps = new Map()
  const used = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new GraphError(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new GraphError(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new GraphError(`error: line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw new GraphError(`error: line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new GraphError(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const x of w.slice(1)) used.push(x)
      used.push(...[])
      used.edges = used.edges || []
      for (const d of w.slice(2)) used.edges.push([w[1], d])
    } else {
      throw new GraphError(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const x of used) if (!cost.has(x)) throw new GraphError(`error: unknown task ${x}`)
  for (const k of cost.keys()) deps.set(k, new Set())
  for (const [a, b] of used.edges || []) deps.get(a).add(b)
  return { cost, deps }
}
