import { GraphError } from './graph.js'

export function analyze({ cost, deps }) {
  const names = [...cost.keys()].sort()
  const sdeps = new Map(names.map((n) => [n, [...deps.get(n)].sort()]))
  const state = new Map()
  const order = []
  for (const root of names) {
    if (state.has(root)) continue
    const stack = [root]
    const idx = [0]
    state.set(root, 1)
    while (stack.length) {
      const top = stack[stack.length - 1]
      const ds = sdeps.get(top)
      const i = idx[idx.length - 1]
      if (i >= ds.length) {
        state.set(top, 2)
        order.push(top)
        stack.pop()
        idx.pop()
        continue
      }
      idx[idx.length - 1]++
      const d = ds[i]
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        throw new GraphError('error: cycle: ' + [...cyc, d].join(' -> '), 3)
      }
      if (!s) {
        state.set(d, 1)
        stack.push(d)
        idx.push(0)
      }
    }
  }
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0n
  for (const n of order) {
    let s = 0n
    let d = 0
    for (const x of sdeps.get(n)) {
      if (finish.get(x) > s) s = finish.get(x)
      if (depth.get(x) + 1 > d) d = depth.get(x) + 1
    }
    start.set(n, s)
    finish.set(n, s + cost.get(n))
    depth.set(n, d)
    if (finish.get(n) > total) total = finish.get(n)
  }
  const prio = new Map()
  for (const n of [...order].reverse()) prio.set(n, cost.get(n))
  for (const n of [...order].reverse()) {
    for (const x of sdeps.get(n)) {
      const v = prio.get(n) + cost.get(x)
      if (v > prio.get(x)) prio.set(x, v)
    }
  }
  return { names, sdeps, start, finish, depth, total, prio }
}

export function pack(graph, workers) {
  const { names, sdeps, prio } = analyze(graph)
  const cost = graph.cost
  const fin = new Map()
  const freeAt = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const pending = [...names]
  let makespan = 0n
  let t = 0n
  while (pending.length) {
    for (;;) {
      let w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = -1
      for (let i = 0; i < pending.length; i++) {
        const n = pending[i]
        if (!sdeps.get(n).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best < 0 || prio.get(n) > prio.get(pending[best])) best = i
      }
      if (best < 0) break
      const [n] = pending.splice(best, 1)
      const f = t + cost.get(n)
      fin.set(n, f)
      freeAt[w] = f
      ran[w].push(`${n}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  const lines = ran.map((r, i) => `worker ${i}:` + r.map((x) => ' ' + x).join(''))
  return { lines, makespan }
}
