const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function parse(s) {
  let rest = s
  const u = { scheme: null, authority: null, path: '', query: null, fragment: null }
  const m = /^([^:/?#]+):/.exec(rest)
  if (m) { u.scheme = m[1]; rest = rest.slice(m[0].length) }
  if (rest.startsWith('//')) {
    const e = rest.slice(2).search(/[/?#]/)
    if (e < 0) { u.authority = rest.slice(2); rest = '' } else { u.authority = rest.slice(2, 2 + e); rest = rest.slice(2 + e) }
  }
  const h = rest.indexOf('#')
  if (h >= 0) { u.fragment = rest.slice(h + 1); rest = rest.slice(0, h) }
  const q = rest.indexOf('?')
  if (q >= 0) { u.query = rest.slice(q + 1); rest = rest.slice(0, q) }
  u.path = rest
  return u
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
