  let userinfo = null, host = '', port = null
  if (u.authority !== null) ({ userinfo, host, port } = splitAuthority(u.authority))
  const checks = [['path', u.path], ['userinfo', userinfo], ['host', host], ['query', u.query], ['fragment', u.fragment]]
