function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.type === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.type === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.value)
}

export const renderJson = (root) => toJson(root, 0) + '\n'

export function renderKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.type === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${n.map.get(k).type}`)
        walk(n.map.get(k), p)
      }
    } else if (n.type === 'array') {
      n.items.forEach((v, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${v.type}`)
        walk(v, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
