function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (node) => [...node.map.keys()].sort(cmp)

function json(node, indent) {
  switch (node.t) {
    case 'table': {
      const ks = sortedKeys(node)
      if (ks.length === 0) return '{}'
      const pad = '  '.repeat(indent + 1)
      const parts = ks.map((k) => `${pad}${JSON.stringify(k)}: ${json(node.map.get(k), indent + 1)}`)
      return `{\n${parts.join(',\n')}\n${'  '.repeat(indent)}}`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const pad = '  '.repeat(indent + 1)
      const parts = node.items.map((v) => pad + json(v, indent + 1))
      return `[\n${parts.join(',\n')}\n${'  '.repeat(indent)}]`
    }
    default:
      return JSON.stringify(node.v)
  }
}

export const renderJson = (root) => json(root, 0) + '\n'

export function renderKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        const c = node.map.get(k)
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
