const newTable = () => ({ t: 'table', map: new Map(), header: false })

class Fail extends Error {
  constructor(msg) {
    super(msg)
    this.confError = true
  }
}
const fail = (m) => {
  throw new Fail(m)
}

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  peek() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  /** True at end of line or at a comment start (after whitespace is skipped). */
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }

  quoted() {
    const q = this.s[this.i++]
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      const cp = String.fromCodePoint(this.s.codePointAt(this.i))
      this.i += cp.length
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail(`invalid escape \\${cp}`)
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }

  value(path) {
    const c = this.peek()
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) {
      if (this.i === st && (this.s[this.i] === '#' || this.s[this.i] === ';')) break
      this.i++
    }
    if (this.i === st) fail('expected a value')
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const run = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${run}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    const f = new RegExp(`^[+-]?${run}(?:\\.${run}(?:[eE][+-]?${run})?|[eE][+-]?${run})$`)
    if (f.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail(`invalid value ${w}`)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(`${path}[${items.length}]`))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      } else fail('trailing text after a value')
    }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      const parts = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      assign(tbl, path, parts, (p) => this.value(p))
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.peek()
      if (c === '}') {
        this.i++
        return tbl
      }
      if (c !== ',') fail('trailing text after a value')
      this.i++
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
    }
  }
}

const join = (p, k) => (p === '' ? k : `${p}.${k}`)

/** Step into the child table named k of tbl, creating it when absent. */
function step(tbl, path, k) {
  const p = join(path, k)
  const c = tbl.map.get(k)
  if (c === undefined) {
    const n = newTable()
    tbl.map.set(k, n)
    return [n, p]
  }
  if (c.t === 'table') return [c, p]
  if (c.t === 'array' && c.aot) return [c.items[c.items.length - 1], p]
  return fail(`${p} is not a table`)
}

function assign(tbl, path, parts, mkValue) {
  let cur = tbl
  let p = path
  for (let n = 0; n < parts.length - 1; n++) [cur, p] = step(cur, p, parts[n])
  const k = parts[parts.length - 1]
  const full = join(p, k)
  if (cur.map.has(k)) fail(`key ${full} is defined twice`)
  cur.map.set(k, mkValue(full))
}

function header(root, lp) {
  const dbl = lp.s[lp.i + 1] === '['
  lp.i += dbl ? 2 : 1
  lp.ws()
  const parts = lp.dotted()
  lp.ws()
  if (lp.peek() !== ']') fail('unterminated table header')
  lp.i++
  if (dbl) {
    if (lp.peek() !== ']') {
      if (lp.peek() === undefined) fail('unterminated table header')
      fail('trailing text after a table header')
    }
    lp.i++
  }
  lp.ws()
  if (!lp.atEnd()) fail('trailing text after a table header')

  let cur = root
  let p = ''
  for (let n = 0; n < parts.length - 1; n++) [cur, p] = step(cur, p, parts[n])
  const k = parts[parts.length - 1]
  const full = join(p, k)
  const c = cur.map.get(k)
  if (dbl) {
    const fresh = newTable()
    if (c === undefined) cur.map.set(k, { t: 'array', items: [fresh], aot: true })
    else if (c.t === 'array' && c.aot) c.items.push(fresh)
    else fail(`${full} is not an array of tables`)
    return fresh
  }
  if (c === undefined) {
    const n = newTable()
    n.header = true
    cur.map.set(k, n)
    return n
  }
  if (c.t !== 'table') fail(`${full} is not a table`)
  if (c.header) fail(`table ${full} is defined twice`)
  c.header = true
  return c
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const lp = new LineParser(lines[n])
      lp.ws()
      const c = lp.peek()
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        cur = header(root, lp)
        curPath = lp.path
        continue
      }
      const parts = lp.dotted()
      lp.ws()
      if (lp.peek() !== '=') fail('expected key = value')
      lp.i++
      lp.ws()
      assign(cur, curPath, parts, (p) => lp.value(p))
      lp.ws()
      if (!lp.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof Fail) e.line = n + 1
      throw e
    }
  }
  return root
}
