        return { t: 'array', items, aot: false }
      } else fail('trailing text after a value')
    }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.peek() === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      const parts = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      assign(tbl, path, parts, (p) => this.value(p))
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.peek()
      if (c === '}') {
        this.i++
        return tbl
      }
      if (c !== ',') fail('trailing text after a value')
      this.i++
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
    }
  }
}

const join = (p, k) => (p === '' ? k : `${p}.${k}`)

/** Step into the child table named k of tbl, creating it when absent. */
function step(tbl, path, k) {
  const p = join(path, k)
  const c = tbl.map.get(k)
  if (c === undefined) {
    const n = newTable()
    tbl.map.set(k, n)
    return [n, p]
  }
  if (c.t === 'table') return [c, p]
  if (c.t === 'array' && c.aot) return [c.items[c.items.length - 1], p]
  return fail(`${p} is not a table`)
}

function assign(tbl, path, parts, mkValue) {
  let cur = tbl
  let p = path
  for (let n = 0; n < parts.length - 1; n++) [cur, p] = step(cur, p, parts[n])
  const k = parts[parts.length - 1]
  const full = join(p, k)
  if (cur.map.has(k)) fail(`key ${full} is defined twice`)
  cur.map.set(k, mkValue(full))
}

function header(root, lp) {
  const dbl = lp.s[lp.i + 1] === '['
  lp.i += dbl ? 2 : 1
  lp.ws()
  const parts = lp.dotted()
  lp.ws()
  if (lp.peek() !== ']') fail('unterminated table header')
  lp.i++
  if (dbl) {
    if (lp.peek() !== ']') {
      if (lp.peek() === undefined) fail('unterminated table header')
      fail('trailing text after a table header')
    }
    lp.i++
  }
  lp.ws()
  if (!lp.atEnd()) fail('trailing text after a table header')

  let cur = root
  let p = ''
  for (let n = 0; n < parts.length - 1; n++) [cur, p] = step(cur, p, parts[n])
  const k = parts[parts.length - 1]
  const full = join(p, k)
  const c = cur.map.get(k)
  if (dbl) {
    const fresh = newTable()
    if (c === undefined) cur.map.set(k, { t: 'array', items: [fresh], aot: true })
    else if (c.t === 'array' && c.aot) c.items.push(fresh)
    else fail(`${full} is not an array of tables`)
    return fresh
  }
  if (c === undefined) {
    const n = newTable()
    n.header = true
    cur.map.set(k, n)
    return n
  }
  if (c.t !== 'table') fail(`${full} is not a table`)
  if (c.header) fail(`table ${full} is defined twice`)
  c.header = true
  return c
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const lp = new LineParser(lines[n])
      lp.ws()
      const c = lp.peek()
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        cur = header(root, lp)
        curPath = lp.path
        continue
      }
      const parts = lp.dotted()
      lp.ws()
      if (lp.peek() !== '=') fail('expected key = value')
      lp.i++
      lp.ws()
      assign(cur, curPath, parts, (p) => lp.value(p))
      lp.ws()
      if (!lp.atEnd()) fail('trailing text after a value')
    } catch (e) {
      if (e instanceof Fail) e.line = n + 1
      throw e
    }
  }
  return root
}
