const mode = args[0]
import { readFileSync } from 'node:fs'

const input = readFileSync(0, 'utf8')
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function int(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

const policies = new Map()
const routes = new Map()
const events = []
let lastTick = null
let seenEvent = false

function parse() {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      handle(t)
    } catch (e) {
      if (e instanceof Fail) {
        process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
}

function handle(t) {
  const d = t[0]
  if (d === 'bucket') {
    if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
    if (seenEvent) throw new Fail('declarations must come before the first event')
    if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
    const capacity = int('capacity', t[2], 1)
    const refill = int('refill', t[3], 0)
    const per = int('per', t[4], 1)
    if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
    policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
  } else if (d === 'window') {
    if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
    if (seenEvent) throw new Fail('declarations must come before the first event')
    if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
    const limit = int('limit', t[2], 0)
    const span = int('span', t[3], 1)
    if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
    policies.set(t[1], { name: t[1], kind: 'window', limit, span })
  } else if (d === 'route') {
    if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
    if (seenEvent) throw new Fail('declarations must come before the first event')
    if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
    if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
    const list = []
    for (const n of t.slice(2)) {
      if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
      list.push(policies.get(n))
    }
    routes.set(t[1], list)
  } else if (d === 'event') {
    if (t.length !== 3) throw new Fail('expected event <tick> <key>')
    const tick = int('tick', t[1], 0)
    if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
    if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
    lastTick = tick
    seenEvent = true
    events.push([tick, t[1], t[2]])
  } else {
    throw new Fail(`unknown directive ${d}`)
  }
}

parse()

const states = new Map() // key -> Map(policy -> state)

function stateFor(key, p, tick) {
  let m = states.get(key)
  if (!m) states.set(key, (m = new Map()))
  let s = m.get(p)
  if (!s) {
    s = p.kind === 'bucket' ? { tokens: p.capacity * p.per, last: tick } : { ticks: [] }
    m.set(p, s)
  }
  return s
}

